function pz_mistakes_cat_indoor_enrichment_guide() {
    return [
        ['❌ Assuming toys left on the floor count as enrichment', 'Cats generally need active, human-involved play, not just access to toys, to get meaningful engagement and exercise.'],
        ['❌ Punishing scratching instead of redirecting it', 'Scratching is a normal, necessary behavior for cats. Punishment doesn\'t address the need and can increase stress; providing appealing scratching outlets works better.'],
        ['❌ Hiding scratching posts in an inconvenient corner', 'Posts tucked away in unused rooms are much less likely to be used than ones placed near where your cat already spends time or scratches.'],
        ['❌ Underestimating how much indoor cats need vertical space', 'Climbing and perching are core feline needs, not optional extras, especially in homes without much floor-level room to roam.'],
        ['❌ Never rotating toys', 'Cats habituate to toys that are always out and visible, which can make enrichment efforts feel ineffective when the real issue is lack of novelty.'],
        ['❌ Overlooking enrichment as a cause of behavior problems', 'Destructive scratching, excessive vocalization, or aggression are often addressed more effectively by adding enrichment than by trying to simply stop the unwanted behavior.'],
    ];
}

